def ic(name,size=18):
 return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+''.join(f'<path d="{p}"/>' for p in [PATHS.get(name,PATHS['grid'])])+'</svg>'
def btn(t,primary=False,icon=None,extra=''):
 return f'<button class="{"primary" if primary else ""} {extra}">{ic(icon) if icon else ""}{t}</button>'
def pill(t,cls=''):
 return f'<span class="pill {cls}">{t}</span>'
def av(name='LN',sz=36,custom=False,color=0):
 return f'<span class="avatar c{color} {"custom-avatar" if custom else ""}" style="width:{sz}px;height:{sz}px;font-size:{int(sz*.32)}px">{ic("spark",int(sz*.53)) if custom else name}</span>'
def tog(on=True):return f'<span class="toggle {"on" if on else ""}"><i></i></span>'
def row(title,desc='',right='',icon=None):
 return f'<div class="row"><div class="row-main">{f"<span class=iconbox>{ic(icon)}</span>" if icon else ""}<div><b>{title}</b>{f"<small>{desc}</small>" if desc else ""}</div></div>{right}</div>'
def field(label,value,extra=''):
 return f'<label class="field"><span>{label}</span><div class="input {extra}">{value}</div></label>'
def card(title,desc,body,icon='sliders',extra=''):
 return f'<section class="card {extra}"><div class="card-head"><span class="iconbox">{ic(icon)}</span><div><h3>{title}</h3><p>{desc}</p></div></div>{body}</section>'
def notice(text,icon='info',extra=''):
 return f'<div class="notice {extra}">{ic(icon)}<span>{text}</span></div>'
def traffic():return '<div class="traffic"><i></i><i></i><i></i></div>'
def tabs(labels,selected=0):return '<div class="tabs">'+''.join(f'<span class="{"selected" if i==selected else ""}">{s}</span>' for i,s in enumerate(labels))+'</div>'
def heading(title,desc,actions=''):
 return f'<div class="page-heading"><div><h1>{title}</h1><p>{desc}</p></div><div class="actions">{actions}</div></div>'

def settings_sidebar(selected='Profilkarte'):
 items=[('settings','Allgemein'),('spark','Erscheinungsbild'),('user','Mein Profil'),('grid','Profilkarte'),('globe','Verbindungen'),('bell','Mitteilungen'),('headphones','Audio & Video'),('lock','Datenschutz')]
 return '<aside class="sidebar"><div class="brand"><span class="brandmark">'+ic('spark',23)+'</span>Diddy<span class="tiny-label">EINSTELLUNGEN</span></div><div class="nav">'+''.join(f'<div class="navitem {"active" if t==selected else ""}">{ic(i)}{t}</div>' for i,t in items)+'</div><div class="sidebar-bottom">'+row('Lndr','@lndr:matrix.example',av('LN',34,True))+'<div class="navitem">'+ic('help')+'Hilfe & Einführung</div></div></aside>'

def profile(layout='standard',compact=False,own=False):
 if compact:
  return '<div class="profile compact-profile">'+row('Lndr '+ic('badge',15),'@lndr:matrix.example',av('LN',44,True))+ '<p class="bio">Design, Code & gute Gespräche.</p>'+pill('Online','online')+btn('Nachricht',True,'message')+'</div>'
 return f'''<div class="profile"><div class="banner"><span class="banner-orbit"></span></div><div class="profile-content"><div class="avatar-overlap">{av('LN',66,True)}<i class="online-dot"></i></div><div class="profile-name">Lndr <span class="profile-badges">{ic('badge',18)}{ic('heart',16)}</span></div><div class="matrix-id">@lndr:matrix.example {ic('copy',12)}</div><div class="statusline"><i></i>Online <span>· Entwirft etwas Neues</span></div>{tabs(['Info','Aktivität','Links'],0) if layout=='tabs' else ''}<div class="profile-divider"></div><div class="eyebrow">ÜBER MICH</div><p class="bio">Design, Code & gute Gespräche.<br>Mein digitales Zuhause.</p>{'<div class="info-pair"><span>Pronomen</span><b>er / ihm</b></div><div class="info-pair"><span>Ort</span><b>Berlin</b></div>' if own else ''}{'<div class="interests">'+pill('Design')+pill('Open Source')+'</div>' if layout=='expanded' else ''}<div class="profile-divider"></div><div class="eyebrow">{('LINKS · FREIWILLIGE ANGABEN' if own else 'GEMEINSAME RÄUME')}</div><div class="shared-room">{ic('link' if own else 'message',16)}{'github.com/lndr' if own else 'Design-Lounge'}<span>{'↗' if own else '+2'}</span></div><div class="profile-divider"></div>{'' if own else '<div class="eyebrow">DEKORATIVE PROFILROLLE</div><div class="role-tag">'+ic('spark',12)+'Open-Source-Fan</div>'}{btn('Nachricht',True,'message')}<div class="profile-meta">{'Nur freigegebene Felder sichtbar' if own else 'Beispieldaten · Standard-Layout'}</div></div></div>'''

def preview(layout='standard',own=False):
 return '<aside class="preview"><div class="preview-heading">'+ic('eye')+'<b>Live-Vorschau</b>'+pill('LIVE','live')+'</div><p class="small muted">Änderungen werden sofort sichtbar.</p>'+profile(layout,own=own)+'<div class="preview-foot">'+ic('info',15)+'So sieht die Karte im Popover aus.</div></aside>'
def settings(body,title,desc,selected='Profilkarte',preview_html=None,tablabels=None,actions=None):
 return '<div class="app">'+f'<header class="titlebar">{traffic()}<span>Diddy · Einstellungen</span>{ic("settings",15)}</header><div class="app-body">'+settings_sidebar(selected)+'<main class="settings-main">'+heading(title,desc,actions or btn('Zurücksetzen')+btn('Änderungen sichern',True))+ (tabs(tablabels) if tablabels else '')+'<div class="settings-columns"><div class="settings-content">'+body+'</div>'+(preview_html or '')+'</div></main></div></div>'

def room_sidebar(selected='Design-Lounge',voice=False):
 return '<aside class="sidebar room-sidebar"><div class="space-title">'+av('D',32,True)+'<b>Diddy Community</b>'+ic('chevron',14)+'</div><div class="navitem">'+ic('message')+'Nachrichten</div><div class="eyebrow section-label">RÄUME <span>+</span></div>'+''.join(f'<div class="navitem {"active" if t==selected else ""}"><span class="hash">#</span>{t}</div>' for t in ['Willkommen','Design-Lounge','Entwicklung'])+'<div class="eyebrow section-label">SPRACHRÄUME <span>+</span></div><div class="navitem '+('active' if voice else '')+'">'+ic('volume')+'Lounge'+pill('3','live')+'</div><div class="voice-avatars">'+av('LN',25,True)+av('ML',25,color=1)+av('SK',25,color=2)+'</div><div class="navitem">'+ic('volume')+'Gaming</div><div class="sidebar-bottom"><div class="self-row">'+av('LN',35,True)+'<div><b>Lndr</b><small>Online</small></div>'+ic('mic',16)+ic('settings',16)+'</div></div></aside>'
def chat_content():
 msgs=[('ML','Mila','14:21','Die neue Oberfläche fühlt sich viel ruhiger an. ✨',1),('LN','Lndr','14:22','Genau das ist die Idee: klare Karten, dezentes Licht und mehr Platz für die wichtigen Dinge.',0),('SK','Sam','14:24','Und die Profilkarte passt jetzt richtig gut dazu.',2)]
 return '<div class="messages"><div class="day-line">Heute</div>'+''.join('<div class="message-row">'+av(n,38,n=='LN',c)+f'<div><b>{t}</b><time>{tm}</time><p>{text}</p></div></div>' for n,t,tm,text,c in msgs)+'</div><div class="composer">'+ic('plus')+'<span>Nachricht an Design-Lounge</span>'+ic('mic')+ic('spark')+'<span class="send">'+ic('arrow')+'</span></div><div class="composer-hint">'+ic('lock',12)+'Ende-zu-Ende verschlüsselt · Enter zum Senden</div>'
def chat_app(content=None,members=True,voice=False):
 member='<aside class="members"><div class="eyebrow">MITGLIEDER — 3</div>'+''.join('<div class="member-row">'+av(n,34,n=='LN',c)+'<div><b>'+t+'</b><small>'+s+'</small></div></div>' for n,t,s,c in [('LN','Lndr','Entwirft etwas Neues',0),('ML','Mila','Online',1),('SK','Sam','Abwesend',2)])+'</aside>' if members else ''
 return '<div class="app"><header class="titlebar">'+traffic()+'<span>Diddy · Community</span>'+ic('globe',15)+'</header><div class="app-body">'+room_sidebar(voice=voice)+'<main class="chat-main"><header class="chat-header"><span class="hash">'+('◌' if voice else '#')+'</span><div><b>'+('Lounge' if voice else 'Design-Lounge')+'</b><small>'+('Sprachraum · Diddy Community' if voice else 'Ein guter Ort für neue Ideen')+'</small></div><div class="spacer"></div>'+ic('headphones')+ic('user')+ic('info')+'</header>'+(content if content is not None else chat_content())+'</main>'+member+'</div></div>'

