DESIGNS=[]
def add(n,title,category,app,notes):
 issue=json.loads((ROOT/'issues-source.json').read_text())
 original=next(x for x in issue if x['number']==n)
 doc='<!doctype html><html lang="de"><head><meta charset="utf-8"><title>'+escape(title)+'</title><style>'+CSS+'</style></head><body><div class="board issue-'+str(n)+'"><div class="board-top"><div><div class="board-kicker">DIDDY / DESIGN DIRECTION / '+category.upper()+'</div><h2>'+title+'</h2></div><div class="issue-pill"><strong>#'+str(n)+'</strong> '+category+' · Soll-Konzept</div></div>'+app+'<div class="footer-notes">'+''.join('<div><div class="note-title"><span>'+str(i+1)+'</span>'+t+'</div><p>'+d+'</p></div>' for i,(t,d) in enumerate(notes))+'</div><div class="board-footer"><span>LNDR2501 / DIDDY · ISSUE #'+str(n)+' · 07.11.2026</span><span>VISUELLE SPEZIFIKATION · BEISPIELDATEN · KEIN IMPLEMENTIERUNGSNACHWEIS</span></div></div></body></html>'
 filename=f'issue-{n:02d}'
 (OUT/(filename+'.html')).write_text(doc)
 DESIGNS.append({'number':n,'title':title,'originalTitle':original['title'],'category':category,'url':original['html_url'],'file':filename,'notes':[{'title':t,'text':d} for t,d in notes]})

# 29 — View preferences, not public identity.
layouts='<div class="layout-options">'
for kind,label,desc in [('compact','Kompakt','Wenig Platz'),('standard','Standard','Ausgewogen'),('expanded','Erweitert','Mehr Details'),('tabs','Tabs','Klar gegliedert')]:
 mini=('<div class="mini-banner"></div>' if kind!='compact' else '')+'<span class="mini-av"></span><span class="mini-line short"></span>'
 if kind=='tabs': mini+='<div class="mini-tabs"><i></i><i></i><i></i></div>'
 mini+='<span class="mini-line"></span><span class="mini-line short"></span>'
 if kind=='expanded':mini+='<span class="mini-line"></span><span class="mini-line short"></span>'
 layouts+=f'<div class="layout-option {"selected" if kind=="standard" else ""}">'+('<span class="selection-check">'+ic('check',11)+'</span>' if kind=='standard' else '')+f'<div class="mini-profile thumb-{kind}">{mini}</div><b>{label}</b><small>{desc}</small></div>'
layouts+='</div>'
mods=''.join(f'<div class="module-row"><span class="handle">⠿</span>{ic(i,15)}<span>{t}</span>{tog(on)}</div>' for i,t,on in [('user','Biografie',True),('music','Aktivitäten',False),('badge','Rollen & Badges',True),('link','Social Links',True),('message','Gemeinsame Räume',True)])
body=notice('Diese Einstellungen ändern, <b>wie du Profile ansiehst</b>. Deine öffentlichen Angaben findest du unter „Mein Profil“.')+card('Dein bevorzugtes Layout','Vier Anordnungen. Dieselben Profilmodule.',layouts,'grid')+'<div class="two">'+card('Module & Reihenfolge','Nur verfügbare Angaben anzeigen.',mods+'<p class="tone-note">Erweitert: Ziehen oder Hoch-/Runter-Tasten.</p>','sliders')+card('Oberfläche & Bewegung','Dezent, lesbar und systemnah.',field('Design','Automatisch '+ic('chevron',13))+row('Glass-Effekt','Kontrast bleibt erhalten',tog(True))+row('Akzentfarbe','', '<div class="swatches"><i style="background:#a76aec"></i><i style="background:#b96191"></i><i style="background:#7987c6"></i></div>')+row('Animationen','Systemeinstellung beachten',tog(True)),'spark')+'</div>'
add(29,'Profilkarten, die sich dir anpassen','Profilkarte',settings(body,'Profilkarte','Darstellung anderer Profile · Layout, Module und Design',preview_html=preview(),tablabels=['Darstellung','Sichtbare Module','Verhalten']),[('Echte Layout-Unterschiede','Kompakt ohne Banner, Standard ausgewogen, Erweitert mit Zusatzfeldern, Tabs mit getrennter Navigation.'),('Ansicht ≠ öffentliche Daten','Layout und sichtbare Module gehören zu lokalen Anzeige-Einstellungen. Eigene Freigaben bleiben separat.'),('Modular & ehrlich','Module teilen Komponenten. Externe Aktivitäten nur mit aktiver Integration; keine erfundenen Daten.')])

# 28 — public data editor.
banner_body='<div class="banner" style="height:68px;border-radius:10px;margin-bottom:10px"></div>'+tabs(['Verlauf','Bild','Einfarbig'])+row('Farben','', '<div class="swatches"><i style="background:#a76aec"></i><i style="background:#5b2a71"></i></div>')+row('Richtung','135°', '<div class="slider"></div>')
identity=field('Anzeigename','Lndr')+'<div class="two">'+field('Schrift','System '+ic('chevron',12))+field('Akzent','#A76AEC')+'</div>'+field('Biografie','Design, Code & gute Gespräche.<br>Ich baue gerade mein digitales Zuhause.','multiline')
optional=field('Pronomen · freiwillig','er / ihm')+field('Ort · freiwillig','Berlin')+field('Website · freiwillig','https://github.com/lndr')+'<p class="tone-note">Zusatzfelder sind ein Vorschlag aus #28. Sichtbarkeit und Synchronisierung vor Umsetzung festlegen.</p>'
avatar_body='<div style="display:flex;align-items:center;gap:15px">'+av('LN',60,True)+'<div>'+btn('Bild ersetzen',False,'upload')+'<small style="margin-top:7px">PNG, WebP oder GIF</small></div></div>'+row('Diddy-Profilbild verwenden','In der gesamten App',tog(True))+row('Position & Zoom','', '<div class="slider" style="width:95px"></div>')+row('Profil-Badges','',pill('2 ausgewählt','live'))
body='<div class="two">'+card('Identität & Kurzinfo','Was andere über dich lesen.',identity,'user')+card('Profilbanner','Licht statt lauter Flächen.',banner_body,'spark')+card('Avatar & Badges','Ein Profilbild, überall konsistent.',avatar_body,'badge')+card('Weitere Informationen','Einzeln freigeben. Jederzeit entfernen.',optional,'info')+'</div>'
add(28,'Dein Profil. Ein klarer Editor.','Profil-Editor',settings(body,'Mein Profil','Öffentliche Angaben bearbeiten · Vorschau rechts',selected='Mein Profil',preview_html=preview(own=True),tablabels=['Identität & Design','Status & Badges','Freigaben']),[('Editor statt Options-Wand','Zwei Kartenspalten für Identität, Banner, Avatar und Zusatzfelder. Vorschau bleibt beim Bearbeiten sichtbar.'),('Felder noch abzustimmen','Pronomen, Ort und Links sind Vorschläge, keine beschlossenen Pflichtfelder. Alles freiwillig und einzeln freigebbar.'),('Mit #29 gemeinsam umsetzen','#28 fokussiert die eigenen Inhalte. #29 definiert modulare Kartenlayouts und lokale Anzeige-Einstellungen.')])

