steps=[('Matrix verstehen','Konto, Server & Räume'),('Von Discord zu Matrix','Begriffe übersetzen'),('Sicher ankommen','Verschlüsselung & Schlüssel'),('Das kann Diddy','Chat, Calls & Streams'),('Gut zu wissen','Grenzen & nächste Schritte')]
