# 7 — connection isolation + lifecycle.
def conn(name,server,initial,status,selected=False,actions=''):
 return '<div class="connection-card '+('selected' if selected else '')+'"><div class="connection-top">'+av(initial,40,selected,0 if selected else 1)+'<div class="connection-name"><b>'+name+'</b><small>'+server+'</small></div>'+status+'</div><div class="connection-meta"><span class="store-tag">'+ic('lock',13)+'Eigener persistenter Datenstore</span><span>·</span><span>Eigenes Fenster</span></div><div class="connection-actions">'+actions+'</div></div>'
connections=conn('Privat','@lndr:matrix.example','LN',pill('Geöffnet','online'),True,btn('Fenster zeigen',False,'monitor'))+conn('Entwicklung','@lndr:dev.example','DE',pill('Öffnen fehlgeschlagen','warn'),False,btn('Entfernen …',False,extra='danger')+btn('Erneut versuchen',True,'refresh'))
body=notice('Jede Verbindung bleibt getrennt: Login, Schlüssel und Web-Daten. Bei Fehlern <b>niemals in den Standard-Datenstore zurückfallen</b>.','shield')+connections+btn('Neue Verbindung hinzufügen',False,'plus')+notice('Entfernen nur nach Bestätigung. Ausschließlich den zu dieser Verbindung gehörenden Store löschen – nicht das primäre Konto.','info')
tests=''.join('<div class="test-row">'+ic(i)+t+pill(p,'warn' if p=='Offen' else 'live')+'</div>' for i,t,p in [('refresh','Timeout → erneuter Versuch','Offen'),('file','Speicherfehler / Abbruch','Offen'),('monitor','Parallele Fenster / Slots','Offen'),('lock','Echte Store-Isolation','Offen'),('clock','Wiederöffnen / Dauertest','Offen')])
aside='<aside class="preview"><div class="preview-heading">'+ic('bug')+'<b>Native Testfälle</b></div><p class="small muted" style="margin:10px 0 16px">Diese Checkliste ist eine Entwickler-Annotation, kein Testergebnis.</p><div class="test-list">'+tests+'</div><p class="tone-note">Unit-Tests prüfen Registry-Regeln. Echte WebKit-Datenstores und Prozessabbrüche brauchen eine laufende macOS-App.</p></aside>'
add(7,'Verbindungen trennen. Fehler sicher abfangen.','Konten & Daten',settings(body,'Verbindungen','Ein Konto pro Fenster · getrennte persistente Daten',selected='Verbindungen',preview_html=aside,actions=btn('Hilfe',False,'help')),[('Fehlerzustand bewusst entwerfen','Timeout lässt gezielten Retry zu. Doppelte Slots, halbe Registry-Einträge und ungesicherte Fenster vermeiden.'),('Isolation ist nicht nur eine Karte','Separate native WebKit-Datenstores beweisen. Primärdaten unverändert; kein Fallback auf einen gemeinsamen Default-Store.'),('Noch offene native Tests','Prozessabbruch, Speicherfehler, paralleles Öffnen und Wiederöffnen sind im Issue weiter offen. Keine grünen Tests erfinden.')])

