viewer_stats='<aside class="stats-panel"><h3>Freigaben von Lndr</h3><small>Du wählst unabhängig aus.</small><div class="stat-box">'+av('LN',48,True)+'<p class="small" style="margin:12px 0">2 parallele Bildschirm-Tracks</p>'+pill('Add-on · Konzept','live')+'</div>'+row('Bildschirm 1','Code · aktuell sichtbar',ic('check',16),'monitor')+row('Bildschirm 2','App-Vorschau',ic('chevron',16),'monitor')+'<div class="notice" style="margin-top:15px">'+ic('info',15)+'<span>Andere Zuschauer können einen anderen Bildschirm ansehen.</span></div></aside>'
content='<div class="caption-line">'+ic('monitor',17)+'Du siehst Lndrs Bildschirm 1'+pill('ZUSCHAUERANSICHT','live')+'</div><div class="stream-stage">'+screen()+viewer_stats+'</div>'+picks+controls
add(2,'Zwei Bildschirme. Deine Perspektive.','Multi-Screen',chat_app(content,members=False,voice=True),[('Zuschauer wählen selbst','Mehrere gleichzeitig angebotene Screen-Tracks. Jeder Zuschauer wechselt unabhängig über Vorschaubilder.'),('Audio bewusst definieren','Vorschlag: nur Ton der ausgewählten Quelle abonnieren, keine Doppelwiedergabe. Technische Zuordnung vor Umsetzung klären.'),('Benötigt RTC-Architekturarbeit','Der aktuelle Element-Call-Einbau bietet nur einen Screen-Track. Add-on erfordert Multi-Track-Support oder einen eigenen Call-Client.')])

(OUT/'manifest.json').write_text(json.dumps(DESIGNS,ensure_ascii=False,indent=2))
print('Created',len(DESIGNS),'mockups in',OUT)
